{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/gosh-sh/acki-nacki/specs/avm-vm/harness/schemas/agent_handoff_packet.schema.json",
  "title": "Agent Handoff Packet",
  "description": "Structured packet passed between AVM implementation swarm roles.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "task_id",
    "iteration_id",
    "supersedes_artifact_ids",
    "owner_specs",
    "owner_modules",
    "public_names_touched",
    "tests_required",
    "perf_artifacts_required",
    "security_boundaries_touched",
    "dependencies_touched",
    "unsafe_requested",
    "open_questions",
    "role_findings",
    "blocking_findings",
    "requested_changes",
    "gate_status"
  ],
  "properties": {
    "schema_version": {
      "const": "1"
    },
    "task_id": {
      "$ref": "#/$defs/stable_id"
    },
    "iteration_id": {
      "type": "integer",
      "minimum": 0
    },
    "supersedes_artifact_ids": {
      "$ref": "#/$defs/stable_id_list"
    },
    "owner_specs": {
      "$ref": "#/$defs/path_list"
    },
    "owner_modules": {
      "$ref": "#/$defs/path_list"
    },
    "public_names_touched": {
      "$ref": "#/$defs/name_list"
    },
    "tests_required": {
      "$ref": "#/$defs/name_list"
    },
    "perf_artifacts_required": {
      "$ref": "#/$defs/name_list"
    },
    "security_boundaries_touched": {
      "$ref": "#/$defs/name_list"
    },
    "dependencies_touched": {
      "$ref": "#/$defs/name_list"
    },
    "unsafe_requested": {
      "type": "boolean"
    },
    "open_questions": {
      "$ref": "#/$defs/text_list"
    },
    "role_findings": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/finding"
      }
    },
    "blocking_findings": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/finding"
      }
    },
    "requested_changes": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/requested_change"
      }
    },
    "gate_status": {
      "type": "object",
      "additionalProperties": {
        "$ref": "#/$defs/gate_decision"
      }
    }
  },
  "$defs": {
    "stable_id": {
      "type": "string",
      "pattern": "^[a-z0-9][a-z0-9._-]*$"
    },
    "stable_id_list": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "$ref": "#/$defs/stable_id"
      }
    },
    "agent_id": {
      "enum": [
        "agent.spec",
        "agent.testing",
        "agent.harness_benchmark",
        "agent.rust",
        "agent.simple",
        "agent.review",
        "agent.storage_state_v2",
        "agent.compatibility",
        "agent.dx_sdk",
        "agent.fuzz_adversarial",
        "agent.performance",
        "agent.security",
        "agent.integration",
        "agent.devops"
      ]
    },
    "severity": {
      "enum": [
        "critical",
        "high",
        "medium",
        "low",
        "nit"
      ]
    },
    "gate_decision": {
      "enum": [
        "pending",
        "LGTM",
        "RequestedChanges",
        "Blocked",
        "NotRelevant"
      ]
    },
    "finding": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "finding_id",
        "from_agent",
        "severity",
        "summary"
      ],
      "properties": {
        "finding_id": {
          "$ref": "#/$defs/stable_id"
        },
        "from_agent": {
          "$ref": "#/$defs/agent_id"
        },
        "severity": {
          "$ref": "#/$defs/severity"
        },
        "summary": {
          "type": "string",
          "minLength": 1
        },
        "evidence": {
          "$ref": "#/$defs/text_list"
        }
      }
    },
    "requested_change": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "change_id",
        "target",
        "summary"
      ],
      "properties": {
        "change_id": {
          "$ref": "#/$defs/stable_id"
        },
        "target": {
          "type": "string",
          "minLength": 1
        },
        "summary": {
          "type": "string",
          "minLength": 1
        },
        "required_regates": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/agent_id"
          }
        }
      }
    },
    "name_list": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string",
        "minLength": 1
      }
    },
    "path_list": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string",
        "minLength": 1
      }
    },
    "text_list": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/gosh-sh/acki-nacki/specs/avm-vm/harness/schemas/avm_task_request.schema.json",
  "title": "AVM Task Request",
  "description": "Runtime command document that starts an AVM implementation swarm process.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "task_id",
    "repo",
    "target",
    "phase_id",
    "goal",
    "scope",
    "constraints",
    "allowed_changes",
    "required_gates",
    "done_definition"
  ],
  "properties": {
    "schema_version": {
      "const": "1"
    },
    "task_id": {
      "$ref": "#/$defs/stable_id"
    },
    "repo": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "owner",
        "name"
      ],
      "properties": {
        "owner": {
          "type": "string",
          "minLength": 1
        },
        "name": {
          "type": "string",
          "minLength": 1
        },
        "remote_url": {
          "type": "string",
          "format": "uri"
        }
      }
    },
    "target": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "kind"
      ],
      "properties": {
        "kind": {
          "enum": [
            "branch",
            "pull_request",
            "commit"
          ]
        },
        "base_branch": {
          "type": "string",
          "minLength": 1
        },
        "head_branch": {
          "type": "string",
          "minLength": 1
        },
        "pull_request_number": {
          "type": "integer",
          "minimum": 1
        },
        "commit_sha": {
          "type": "string",
          "pattern": "^[0-9a-f]{40}$"
        }
      }
    },
    "phase_id": {
      "enum": [
        "phase_0",
        "phase_1",
        "phase_2",
        "phase_3",
        "phase_4",
        "phase_5",
        "phase_6",
        "phase_7",
        "phase_8",
        "phase_9",
        "phase_10",
        "phase_11",
        "cross_phase"
      ]
    },
    "goal": {
      "type": "string",
      "minLength": 1
    },
    "scope": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "owner_specs",
        "owner_modules",
        "files"
      ],
      "properties": {
        "owner_specs": {
          "$ref": "#/$defs/path_list"
        },
        "owner_modules": {
          "$ref": "#/$defs/path_list"
        },
        "crates": {
          "$ref": "#/$defs/name_list"
        },
        "files": {
          "$ref": "#/$defs/path_list"
        },
        "public_names_touched": {
          "$ref": "#/$defs/name_list"
        }
      }
    },
    "constraints": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "docs_english_only",
        "names_update_required",
        "safe_rust_default",
        "unsafe_requires_escalation",
        "no_unapproved_dependencies",
        "no_hidden_behavior"
      ],
      "properties": {
        "docs_english_only": {
          "type": "boolean"
        },
        "names_update_required": {
          "type": "boolean"
        },
        "safe_rust_default": {
          "type": "boolean"
        },
        "unsafe_requires_escalation": {
          "type": "boolean"
        },
        "no_unapproved_dependencies": {
          "type": "boolean"
        },
        "no_hidden_behavior": {
          "type": "boolean"
        }
      }
    },
    "allowed_changes": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "enum": [
          "docs",
          "specs",
          "modules",
          "source",
          "tests",
          "ci",
          "benchmarks",
          "harness",
          "schemas",
          "skills"
        ]
      }
    },
    "required_gates": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "$ref": "#/$defs/gate_id"
      }
    },
    "perf_profile": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "profile_id"
      ],
      "properties": {
        "profile_id": {
          "$ref": "#/$defs/stable_id"
        },
        "machine_profile_binding": {
          "$ref": "#/$defs/stable_id"
        },
        "dataset_id": {
          "$ref": "#/$defs/stable_id"
        }
      }
    },
    "done_definition": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string",
        "minLength": 1
      }
    }
  },
  "$defs": {
    "stable_id": {
      "type": "string",
      "pattern": "^[a-z0-9][a-z0-9._-]*$"
    },
    "gate_id": {
      "enum": [
        "spec",
        "testing",
        "harness_benchmark",
        "simple",
        "review",
        "storage_state_v2",
        "compatibility",
        "dx_sdk",
        "fuzz_adversarial",
        "performance",
        "security",
        "integration",
        "devops"
      ]
    },
    "name_list": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string",
        "minLength": 1
      }
    },
    "path_list": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string",
        "minLength": 1
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/gosh-sh/acki-nacki/specs/avm-vm/harness/schemas/experiment_record.schema.json",
  "title": "AVM Experiment Evidence Record",
  "description": "Append-only structured evidence emitted by AVM swarm loops for measurable changes, regressions, failure analysis, and follow-up decisions.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "record_id",
    "parent_record_id",
    "experiment_kind",
    "task_id",
    "iteration_id",
    "status",
    "component",
    "module_or_function",
    "git_sha",
    "spec_refs",
    "hypothesis",
    "baseline",
    "change_made",
    "controlled_variable",
    "commands",
    "environment",
    "machine_profile",
    "inputs",
    "metrics_before",
    "metrics_after",
    "profiler_refs",
    "failure_signature",
    "verdict",
    "next_action",
    "produced_artifacts",
    "memory_evidence"
  ],
  "properties": {
    "schema_version": {
      "const": "1"
    },
    "record_id": {
      "$ref": "#/$defs/stable_id"
    },
    "parent_record_id": {
      "anyOf": [
        {
          "$ref": "#/$defs/stable_id"
        },
        {
          "type": "null"
        }
      ]
    },
    "experiment_kind": {
      "enum": [
        "generic",
        "performance",
        "security",
        "refactor",
        "failure_analysis"
      ]
    },
    "task_id": {
      "$ref": "#/$defs/stable_id"
    },
    "iteration_id": {
      "type": "integer",
      "minimum": 0
    },
    "status": {
      "enum": [
        "planned",
        "completed",
        "blocked",
        "superseded"
      ]
    },
    "component": {
      "type": "string",
      "minLength": 1
    },
    "module_or_function": {
      "type": "string",
      "minLength": 1
    },
    "git_sha": {
      "type": "string",
      "pattern": "^[0-9a-f]{40}$"
    },
    "spec_refs": {
      "$ref": "#/$defs/text_list"
    },
    "hypothesis": {
      "type": "string",
      "minLength": 1
    },
    "baseline": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "description",
        "git_sha",
        "record_refs",
        "artifact_refs"
      ],
      "properties": {
        "description": {
          "type": "string",
          "minLength": 1
        },
        "git_sha": {
          "anyOf": [
            {
              "type": "string",
              "pattern": "^[0-9a-f]{40}$"
            },
            {
              "type": "null"
            }
          ]
        },
        "record_refs": {
          "$ref": "#/$defs/stable_id_list"
        },
        "artifact_refs": {
          "$ref": "#/$defs/text_list"
        }
      }
    },
    "change_made": {
      "type": "string",
      "minLength": 1
    },
    "controlled_variable": {
      "type": "string",
      "minLength": 1
    },
    "commands": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "command",
          "cwd"
        ],
        "properties": {
          "command": {
            "type": "string",
            "minLength": 1
          },
          "cwd": {
            "type": "string",
            "minLength": 1
          },
          "exit_code": {
            "type": "integer"
          },
          "env": {
            "type": "object",
            "additionalProperties": {
              "type": "string"
            }
          }
        }
      }
    },
    "environment": {
      "type": "object",
      "additionalProperties": true
    },
    "machine_profile": {
      "type": "object",
      "additionalProperties": true
    },
    "inputs": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "kind",
          "id",
          "description"
        ],
        "properties": {
          "kind": {
            "type": "string",
            "minLength": 1
          },
          "id": {
            "type": "string",
            "minLength": 1
          },
          "description": {
            "type": "string",
            "minLength": 1
          },
          "hash_sha256": {
            "type": "string",
            "pattern": "^[0-9a-f]{64}$"
          }
        }
      }
    },
    "metrics_before": {
      "type": "object",
      "additionalProperties": true
    },
    "metrics_after": {
      "type": "object",
      "additionalProperties": true
    },
    "profiler_refs": {
      "$ref": "#/$defs/text_list"
    },
    "failure_signature": {
      "anyOf": [
        {
          "type": "object",
          "additionalProperties": true
        },
        {
          "type": "null"
        }
      ]
    },
    "verdict": {
      "enum": [
        "accepted",
        "rejected",
        "inconclusive",
        "blocked",
        "regression"
      ]
    },
    "next_action": {
      "type": "string",
      "minLength": 1
    },
    "produced_artifacts": {
      "$ref": "#/$defs/text_list"
    },
    "memory_evidence": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "operation",
          "query"
        ],
        "properties": {
          "operation": {
            "enum": [
              "memory_recall",
              "get_more_context",
              "memory_query"
            ]
          },
          "query": {
            "type": "string",
            "minLength": 1
          },
          "evidence_refs": {
            "$ref": "#/$defs/text_list"
          }
        }
      }
    }
  },
  "$defs": {
    "stable_id": {
      "type": "string",
      "pattern": "^[a-z0-9][a-z0-9._-]*$"
    },
    "stable_id_list": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "$ref": "#/$defs/stable_id"
      }
    },
    "text_list": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/gosh-sh/acki-nacki/specs/avm-vm/harness/schemas/gate_feedback_packet.schema.json",
  "title": "Gate Feedback Packet",
  "description": "Structured feedback emitted by a required gate when an AVM implementation task must re-enter an earlier step.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "task_id",
    "iteration_id",
    "from_agent",
    "gate_decision",
    "target_reentry_step",
    "blocking_findings",
    "requested_changes",
    "supersedes_artifact_ids",
    "required_regates"
  ],
  "properties": {
    "schema_version": {
      "const": "1"
    },
    "task_id": {
      "$ref": "#/$defs/stable_id"
    },
    "iteration_id": {
      "type": "integer",
      "minimum": 0
    },
    "from_agent": {
      "$ref": "#/$defs/gate_agent_id"
    },
    "gate_decision": {
      "enum": [
        "RequestedChanges",
        "Blocked"
      ]
    },
    "target_reentry_step": {
      "enum": [
        "step.spec_map",
        "step.test_plan",
        "step.benchmark_plan",
        "step.implement",
        "step.devops"
      ]
    },
    "blocking_findings": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/$defs/finding"
      }
    },
    "requested_changes": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/$defs/requested_change"
      }
    },
    "supersedes_artifact_ids": {
      "$ref": "#/$defs/stable_id_list"
    },
    "required_regates": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "$ref": "#/$defs/gate_agent_id"
      }
    }
  },
  "$defs": {
    "stable_id": {
      "type": "string",
      "pattern": "^[a-z0-9][a-z0-9._-]*$"
    },
    "stable_id_list": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "$ref": "#/$defs/stable_id"
      }
    },
    "gate_agent_id": {
      "enum": [
        "agent.spec",
        "agent.simple",
        "agent.review",
        "agent.storage_state_v2",
        "agent.compatibility",
        "agent.dx_sdk",
        "agent.fuzz_adversarial",
        "agent.performance",
        "agent.security",
        "agent.integration",
        "agent.devops"
      ]
    },
    "severity": {
      "enum": [
        "critical",
        "high",
        "medium",
        "low",
        "nit"
      ]
    },
    "finding": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "finding_id",
        "severity",
        "summary"
      ],
      "properties": {
        "finding_id": {
          "$ref": "#/$defs/stable_id"
        },
        "severity": {
          "$ref": "#/$defs/severity"
        },
        "summary": {
          "type": "string",
          "minLength": 1
        },
        "evidence": {
          "$ref": "#/$defs/text_list"
        }
      }
    },
    "requested_change": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "change_id",
        "target",
        "summary"
      ],
      "properties": {
        "change_id": {
          "$ref": "#/$defs/stable_id"
        },
        "target": {
          "type": "string",
          "minLength": 1
        },
        "summary": {
          "type": "string",
          "minLength": 1
        }
      }
    },
    "text_list": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      }
    }
  }
}
